  "legal.backToSite": "← Torna al sito",
  "legal.lastUpdate": "Ultimo aggiornamento: {date}",
  "legal.draftNote": "Questo documento è una bozza tecnica e va validato da un consulente legale prima della pubblicazione definitiva.",
  "priv.intro": "LyftAI (\"noi\", \"l'applicazione\") è una piattaforma di analytics e marketing intelligence per e-commerce. Questa informativa descrive quali dati trattiamo, come e perché, quando un commerciante (\"merchant\") collega i propri account (Shopify, Meta, Google, Klaviyo e altre piattaforme) a LyftAI.",
  "priv.h1": "1. Dati che trattiamo",
  "priv.p1a": "Quando il merchant autorizza una connessione, LyftAI accede in sola lettura ai dati necessari a generare report e analisi, tra cui:",
  "priv.shopify": "ordini, prodotti, clienti (aggregati: numero ordini, spesa, data di acquisizione), report/analytics, inventario, sconti, evasioni. Usati per metriche di vendita, LTV, coorti, attribuzione.",
  "priv.adPlatforms": "Piattaforme pubblicitarie",
  "priv.and": "e",
  "priv.adData": "spesa, impression, click, conversioni, performance delle campagne.",
  "priv.emailTools": "e strumenti collegati (Gmail, Slack), secondo gli scope autorizzati.",
  "priv.p1b": "Non vendiamo né cediamo i dati a terzi per finalità di marketing. Non usiamo i dati personali dei clienti del merchant per profilazione propria.",
  "priv.h2": "2. Token di accesso",
  "priv.p2pre": "Le autorizzazioni OAuth e i token di accesso sono gestiti e custoditi tramite il nostro provider di integrazione (",
  "priv.p2post": "). I token sono cifrati e usati esclusivamente per leggere i dati del merchant che li ha autorizzati. Il merchant può revocarli in qualsiasi momento.",
  "priv.h3": "3. Finalità del trattamento",
  "priv.p3": "Trattiamo i dati esclusivamente per fornire al merchant le funzionalità di LyftAI: dashboard, KPI, report PDF, analisi di attribuzione, LTV/coorti, raccomandazioni e assistenti AI sui suoi stessi dati.",
  "priv.h4": "4. Dati Google e conformità Google API Services",
  "priv.p4": "Quando il merchant collega il proprio account Google, LyftAI richiede l'accesso in sola lettura ai seguenti ambiti (scope), unicamente per mostrare al merchant i propri dati all'interno dell'applicazione:",
  "priv.gAds": "performance delle campagne (spesa, impression, click, conversioni, ROAS).",
  "priv.gGa4": "sessioni, sorgenti di traffico, conversioni.",
  "priv.gGsc": "query, impression e posizionamento organico.",
  "priv.gBq": "lettura di dataset di analytics, ove configurati dal merchant.",
  "priv.h5": "5. Sub-responsabili (sub-processors)",
  "priv.subVercel": "hosting dell'applicazione",
  "priv.subNango": "gestione OAuth e token",
  "priv.subOpenai": "elaborazione delle richieste agli assistenti AI (dati aggregati di performance, non PII dei clienti)",
  "priv.subBrowserless": "generazione PDF e screenshot (browser headless)",
  "priv.subSupabase": "autenticazione e dati applicativi dei merchant",
  "priv.subGoogleAi": "elaborazione AI delle richieste (dati aggregati, niente PII)",
  "priv.subFal": "generazione di immagini e video (Creative Studio)",
  "priv.subEleven": "sintesi vocale per gli assistenti AI",
  "priv.subStripe": "pagamenti e abbonamenti",
  "priv.subResend": "invio di email di report e notifiche",
  "priv.subScreenshot": "screenshot delle pagine (AI Website Scanner)",
  "priv.subLivekit": "chiamate audio/video di gruppo",
  "priv.subRailway": "hosting del worker delle chiamate",
  "priv.h6": "6. Conservazione e cancellazione",
  "priv.p6pre": "LyftAI legge i dati di vendita e marketing prevalentemente in tempo reale e non conserva dati personali identificativi dei clienti finali oltre a quanto necessario per la cache tecnica. Il merchant può disconnettere una piattaforma in qualsiasi momento: in tal caso interrompiamo l'accesso e revochiamo i token. Per i dati Google, l'utente può inoltre revocare l'accesso da ",
  "priv.p6link": "Google Account → Sicurezza → App di terze parti",
  "priv.p6b": "Rispettiamo i webhook di conformità di Shopify:",
  "priv.whData": "richiesta dati di un cliente",
  "priv.whRedact": "cancellazione dati di un cliente",
  "priv.whShop": "cancellazione dati dello shop dopo la disinstallazione",
  "priv.h7": "7. Sicurezza",
  "priv.p7": "Usiamo connessioni cifrate (TLS), accesso ai dati con privilegio minimo (solo scope in lettura) e token gestiti in modo sicuro. L'accesso applicativo è protetto da autenticazione.",
  "priv.h8": "8. Diritti dell'interessato",
  "priv.p8": "I clienti finali del merchant possono esercitare i propri diritti (accesso, rettifica, cancellazione) tramite il merchant, titolare del trattamento. LyftAI agisce come responsabile del trattamento per conto del merchant.",
  "priv.h9": "9. Titolare e contatti",
  "priv.contact": "Per qualsiasi richiesta relativa alla privacy:",
  "terms.title": "Termini di Servizio",
  "terms.intro": "I presenti Termini di Servizio (\"Termini\") regolano l'utilizzo di LyftAI (\"il Servizio\", \"noi\"), piattaforma di analytics e marketing intelligence per e-commerce. Utilizzando il Servizio, l'utente (\"tu\", \"il merchant\") accetta i presenti Termini.",
  "terms.h1": "1. Descrizione del servizio",
  "terms.p1pre": "LyftAI consente al merchant di collegare i propri account (Shopify, Meta, Google, GA4, Klaviyo e altre piattaforme) per visualizzare dashboard, KPI, report, analisi di attribuzione, LTV/coorti e raccomandazioni basate sui propri dati. L'accesso ai dati collegati avviene in ",
  "terms.readonly": "sola lettura",
  "terms.h2": "2. Account e accesso",
  "terms.p2": "Il merchant è responsabile della riservatezza delle proprie credenziali e di tutte le attività svolte tramite il proprio account. Le autorizzazioni alle piattaforme collegate possono essere revocate in qualsiasi momento disconnettendo l'integrazione.",
  "terms.h3": "3. Uso consentito",
  "terms.p3": "Il merchant si impegna a utilizzare il Servizio in conformità alle leggi applicabili e ai termini delle piattaforme collegate (incluse le policy di Google API Services, Shopify e Meta). È vietato tentare di accedere a dati di altri merchant, effettuare reverse engineering o usare il Servizio per finalità illecite.",
  "terms.h4": "4. Dati e privacy",
  "terms.p4pre": "Il trattamento dei dati è descritto nella nostra ",
  "terms.p4mid": ". LyftAI agisce come responsabile del trattamento per conto del merchant, titolare dei dati dei propri clienti. L'uso dei dati ottenuti dalle API Google rispetta la ",
  "terms.p4post": ", inclusi i requisiti di Limited Use.",
  "terms.h5": "5. Disponibilità e modifiche",
  "terms.p5": "Ci impegniamo a mantenere il Servizio disponibile, ma non garantiamo un funzionamento ininterrotto o privo di errori. Possiamo modificare, sospendere o interrompere funzionalità del Servizio, dandone comunicazione quando ragionevolmente possibile.",
  "terms.h6": "6. Limitazione di responsabilità",
  "terms.p6": "Il Servizio è fornito \"così com'è\". Nei limiti consentiti dalla legge, LyftAI non è responsabile per danni indiretti, perdita di dati o mancati guadagni derivanti dall'uso del Servizio. Le decisioni di business basate sui report restano responsabilità del merchant.",
  "terms.h7": "7. Cessazione",
  "terms.p7": "Il merchant può cessare l'utilizzo del Servizio in qualsiasi momento. Possiamo sospendere o chiudere un account in caso di violazione dei presenti Termini. Alla cessazione, gli accessi alle piattaforme collegate vengono revocati.",
  "terms.h8": "8. Contatti",
  "terms.p8": "Per richieste relative ai presenti Termini:",
