  "geo.howT": "Come leggere questi dati",
  "geo.dGeoT": "Perché il geo-lift",
  "geo.dGeoD": "È un esperimento vero: alcune regioni ricevono più (o meno) budget, altre no. La differenza è causale — toglie il bias dei modelli osservazionali.",
  "geo.dMatchT": "Qualità del matching",
