  "geo.note": "Le regioni e la metrica arrivano da GA4. Questa è la fase di progettazione; dopo aver fatto girare il test, il readout (differenza-nelle-differenze) conferma il lift causale.",
  "geo.fuori": "{n} province non si sono potute ricondurre a una regione: €{e} restano fuori dal disegno.",
  "curvesExp.title": "Come leggere questi dati",
  "curvesExp.d1T": "Curva di risposta",
  "curvesExp.d1D": "Mostra quanto ricavo incrementale porta ogni livello di spesa giornaliera. All'inizio sale ripida, poi si appiattisce (rendimenti decrescenti).",
  "curvesExp.d2T": "Il punto 'ora'",
  "curvesExp.d2D": "La linea verticale e il pallino sono la tua spesa attuale. A sinistra (verde) ogni euro rende ancora bene; a destra (rosso) stai saturando.",
  "curvesExp.d3T": "Saturazione",
  "curvesExp.d3D": "La % indica quanto sei vicino al tetto della curva. Sopra ~80% aggiungere budget rende poco.",
  "curvesExp.d4T": "Carryover",
  "curvesExp.d4D": "Le barre mostrano per quanti giorni l'euro speso oggi continua a portare vendite (qui i giorni per il 90% dell'effetto).",
  "geo.step1": "In {c}, aumenta la spesa del {p}% solo nelle {n} regioni TEST (geo-targeting).",
  "geo.testHint": "applica qui +{p}% {c}",
  "geo.controlsNote": "Regioni, durata e statistiche dipendono dai tuoi dati e sono uguali per ogni canale. Il canale e la % di spesa sono il trattamento che applichi nelle regioni test — li trovi nel Piano qui sotto.",
  "geo.mdeByDuration": "Lift rilevabile per durata:",
  "incr.conservativeNote": "Stima conservativa (limite inferiore): con gli ads sempre attivi il modello non vede mai 'spesa zero', quindi l'incrementale reale è probabilmente più alto. Il geo-lift lo rivela.",
  "incr.methodNote": "Stima realistica: partiamo dal ricavo riportato dalle piattaforme e applichiamo fattori di incrementalità tipici dell'e-commerce (Meta ~70%, Google ~55%, ridotti dalla saturazione), con una quota minima di baseline organico. Sono prior: il geo-lift dà la certezza.",
  "incr.totalAdSpend": "Spesa ads totale",
  "incr.onSpend": "su {s} di spesa",
  "incr.reportedEst": "riportato ~{v} (stimato)",
  "reco.title": "Azioni proattive & to-do",
  'reco.cut': 'Metti in pausa la crescita su {c}: il prossimo euro rende {x} (sotto 1× = al margine ci perdi). Come: congela il budget attuale per 7 giorni e sposta l\'extra sul canale col miglior €-marginale. Impatto: ogni €100/giorno non spesi qui sono margine salvato; ricontrolla la curva dopo una settimana.',
  'reco.scale': 'Scala {c}: il prossimo euro rende {x} e sei saturo solo al {s} — c\'è spazio reale. Come: aumenta il budget del 15-20% ogni 3-4 giorni (mai raddoppi secchi) e osserva il ROAS marginale. Impatto: a parità di curva, +€100/giorno ≈ +€{x}00/giorno di ricavo incrementale; fermati quando il marginale scende verso 1×.',
  'reco.overclaim': 'Non fidarti del ROAS di {c}: la piattaforma dichiara {rep} ma l\'incrementale reale è {ir} (gonfiato ~{p}). Perché: si attribuisce vendite che avresti fatto comunque. Come: decidi i budget sul ROAS incrementale e imposta il break-even di conseguenza. Impatto: eviti di scalare un canale che sembra profittevole ma al margine non lo è.',
  'reco.realloc': 'Sposta budget da {from} (marginale basso) a {to} (prossimo € = {x}): stesso budget totale, più ricavo incrementale. Come: trasferisci il 10-15% a settimana, non tutto insieme, e ricontrolla le curve dopo ogni passo. Impatto: la differenza di €-marginale tra i due canali è guadagno netto a costo zero; fai rollback se il marginale di {to} scende sotto quello di {from}.',
  'reco.importGoogle': 'Importa il valore di conversione di Google Ads: oggi il suo ricavo è STIMATO e l\'analisi del canale è approssimativa. Come: in Google Ads attiva il tag di conversione con valore (o l\'import da GA4) — 15 minuti di setup. Impatto: la ripartizione incrementale su Google diventa precisa e le decisioni di budget sul canale smettono di basarsi su un prior.',
  "reco.lowConf": "Affidabilità bassa (R² {r2}): il totale è solido ma lo split tra canali è incerto — valida con un geo-lift prima di spostamenti grossi.",
  'reco.lowConf2': 'Affidabilità limitata: il totale è solido ma lo split per canale è incerto. Come: prima di grossi spostamenti di budget valida con un geo-lift (2-4 settimane, escludi 2-3 regioni). Impatto: eviti di riallocare migliaia di € sulla base di uno split che potrebbe cambiare; il geo-lift ti dà la prova sperimentale.',
  "incr.confWhy": "Perché",
  "incr.confDays": "{d} giorni di dati",
  "incr.confRepOk": "ricavi riportati reali dalle piattaforme",
  "incr.confRepEst": "parte dei ricavi riportati è stimata (importa il valore conversioni)",
  "incr.confSanityBad": "attribuzione sopra il fatturato (double counting)",
  "incr.confFlat": "spesa stabile (normale per always-on)",
  'reco.curveSat': '{c} è oltre il punto efficiente ({s} saturo): tagliare spesa MIGLIORA l\'efficienza, non la peggiora. Come: riduci il budget del 15% a settimana finché il €-marginale non risale sopra 1.2×. Impatto: stessi ricavi (o quasi) con meno spesa = margine diretto; monitora che il fatturato del canale non cali più del previsto dalla curva.',
  'reco.curveRoom': '{c} ha spazio sulla curva (prossimo € = {x}): aumenta gradualmente e rimisura. Come: +15-20% di budget ogni 3-4 giorni, mai in un colpo solo, e verifica che il marginale resti sopra 1.2×. Impatto: crescita di ricavo incrementale a efficienza quasi invariata finché resti nella parte ripida della curva.',
  'reco.carry': 'Il carryover di {c} è {d} giorni: parte delle vendite arriva DOPO la spesa. Come: non giudicare (né spegnere) le campagne {c} prima di {d} giorni dal cambio budget. Impatto: eviti di uccidere campagne che stanno ancora maturando — l\'errore più comune e costoso su questo canale.',
  "reco.simRealloc": "Prova lo spostamento suggerito: sposta budget da {from} a {to} e guarda l'incrementale salire.",
  "reco.simScale": "{c} ha prossimo € {x}: alza il suo slider di ~20% e guarda il guadagno incrementale.",
  "reco.geoRun": "Lancia il geo-lift su {c}: {w} settimane, rileverai un lift ≥ {mde}. È la prova causale dell'incrementalità.",
  "reco.geoMatchGood": "Matching {p}%: il control segue bene il test, l'esperimento sarà affidabile.",
  "reco.geoMatchWeak": "Matching {p}% (debole): usa un periodo pre-test più lungo o regioni più omogenee per un risultato solido.",
  "incr.halfSat": "mezza-sat ~{s}/g",
  "incr.satNote": "La saturazione è una stima ancorata alla tua distribuzione di spesa (ginocchio per canale), non misurata: il geo-lift rivela la curva reale.",
