  "cor.g.perimetri7": "Quando il paese di spedizione manca, si usa quello di fatturazione: arrivano dalla stessa interrogazione, quindi il registro resta una sola contabilita. Le righe dedotte cosi vengono contate e dichiarate a parte.",
