  "cor.giftBody2": "Le gift card monouso si tassano all emissione: il corrispettivo nasce quando il cliente le acquista. Al riscatto l importo va neutralizzato, altrimenti la merce pagata con la gift card verrebbe tassata una seconda volta. Shopify esclude le emissioni dal totale vendite, quindi qui vengono riaggiunte.",
