  "cor.g.export8": "GIFT CARD: ogni emissione, riscatto e riaccredito con il suo effetto sul corrispettivo. QUADRATURA: i controlli superati o falliti.",
  "cor.g.shopify4": "Il corrispettivo fiscale aggiunge a queste vendite le gift card emesse e sottrae quelle riscattate: Shopify non le conta nel totale vendite.",
  "cor.g.panoramicaT": "Cosa fa il registro e da dove arrivano i dati.",
  "cor.g.panoramica1": "Fonte unica: Shopify Analytics (ShopifyQL), raggruppato per giorno e paese di spedizione.",
  "cor.g.panoramica2": "I totali sono per giorno, paese e regime fiscale: Italia, IVA OSS, extra-UE.",
  "cor.g.panoramica3": "Include tutti i canali di vendita, marketplace compresi: restano vendite dell’azienda.",
  "cor.g.panoramica4": "Un mese per richiesta, anche sui mesi passati.",
  "cor.g.perimetriT": "Italia, OSS, extra-UE e casi da verificare.",
  "cor.g.perimetri1": "paese di spedizione IT, vendite domestiche.",
  "cor.g.perimetri2": "paesi UE non italiani, con l’aliquota ordinaria del paese di destinazione.",
  "cor.g.perimetri3": "fuori UE: IVA 0%.",
  "cor.g.perimetri4": "paese mancante su Shopify: la riga non viene attribuita a nessun regime.",
  "cor.g.perimetri5": "L'IVA è quella che Shopify ha registrato sull'ordine, e l'imponibile è il lordo meno quell'IVA: è l'imposta davvero applicata quel giorno, non una ricostruzione. Dove Shopify non la fornisce si scorpora con l'aliquota ordinaria del paese, e la riga lo dichiara.",
  "cor.g.perimetri6": "L'aliquota mostrata è quella EFFETTIVA, dedotta dai numeri: un negozio che vende al 4, al 10 e al 22 non ha una sola aliquota. Il limite resta sulle sole righe senza IVA da Shopify, dove i territori speciali (Livigno, Campione, Canarie) restano approssimati all'aliquota del paese.",
  "cor.g.shopifyT": "Vendite, paese e quadratura interna.",
  "cor.g.formula": "Corrispettivo = vendite lorde + sconti + resi + spedizioni + IVA + commissioni di reso",
  "cor.g.shopify1": "Sconti e resi arrivano già con segno negativo e seguono la data del report, cioè il giorno contabile del movimento.",
  "cor.g.shopify2": "Due identità devono chiudere entro 2 centesimi: lordo + sconti + resi = netto, e netto + spedizioni + IVA + commissioni = totale.",
  "cor.g.shopify3": "Se non chiudono, il registro lo dice e non va consegnato.",
  "cor.g.giftT": "Gift card monouso: IVA all’emissione.",
  "cor.g.gift1": "Il corrispettivo nasce all’acquisto della gift card, non al suo utilizzo.",
  "cor.g.gift2": "Al riscatto l’importo va neutralizzato, altrimenti la stessa somma sarebbe tassata due volte.",
  "cor.g.exportT": "Fogli dell’Excel per il commercialista.",
  "cor.g.export1": "questa guida, dentro il file.",
  "cor.g.export2": "totali per regime fiscale e paese.",
  "cor.g.export3": "tutte le righe: giorno, regime, paese, ordini, resi, lordo, imponibile, IVA.",
  "cor.g.export4": "solo perimetro Italia.",
  "cor.g.export5": "solo vendite UE non italiane, con aliquota per paese.",
  "cor.g.export7": "Nome del file: corrispettivi-shopify-AAAA-MM.xlsx",
  "cor.g.quadraturaT": "Controlli prima di consegnare al commercialista.",
  "cor.g.quadratura1": "Le due identità contabili devono essere verdi: se una salta, il mese non è consegnabile.",
  "cor.g.quadratura2": "Il lordo senza paese deve essere vicino a zero: ogni euro lì dentro è una vendita senza regime IVA.",
  "cor.g.quadratura3": "Il mese deve essere chiuso: su un mese in corso il registro cambia ancora.",
  "cor.g.quadratura4": "Confronta il corrispettivo del periodo con il totale vendite del pannello Shopify: devono coincidere.",
  "klaviyo.feedScope": "Questa email ha {n} blocchi di prodotti dinamici. Per vederne le immagini serve il permesso web-feeds:read su Klaviyo: aggiungilo agli scope dell app e ricollega Klaviyo dalle Integrazioni. Il resto dell email e gia quello vero.",
  "klaviyo.feedNow": "I prodotti nei blocchi dinamici sono quelli del feed OGGI: al momento dell invio potevano essere altri.",
  "klaviyo.feedEmpty": "I blocchi di prodotti dinamici risultano vuoti: il feed non risponde o non contiene articoli.",
  "klaviyo.feedScope1": "Lo spazio vuoto qui sotto e un blocco di prodotti dinamici: Klaviyo lo riempie all invio leggendo un feed, e per mostrartelo serve il permesso web-feeds:read. Aggiungilo agli scope dell app Klaviyo, poi su Nango, infine ricollega dalle Integrazioni. Il resto dell email e gia quello vero.",
  "klaviyo.feedNoApi": "Gli spazi vuoti sono blocchi di prodotti dinamici. Klaviyo li calcola solo al momento dell invio e non li espone da nessuna API: nemmeno la sua anteprima e ricostruibile da fuori. Oggetto, testi e struttura qui sopra sono invece quelli veri.",
  "klaviyo.feedRicostruito": "I prodotti nei blocchi dinamici sono RICOSTRUITI dal tuo catalogo: i piu venduti del marchio e della categoria indicati dal blocco, negli ultimi 90 giorni. Klaviyo sceglie i suoi al momento dell invio e non li espone, quindi questi non sono necessariamente quelli che ha visto il destinatario.",
